insert into public.equipment(kind,name,is_default) select v.kind,v.name,v.d from (values ('grinder','Timemore C3s',true),('dripper','Origami Air M',true),('moka','3 Cup',true),('filter','ORIGAMI Cone',false),('filter','CAFEC Abaca',false),('filter','ORIGAMI Wave',false),('sweetener','Condensed Milk',true),('sweetener','Sugar',false),('sweetener','Coconut Sugar',false)) v(kind,name,d) where not exists(select 1 from public.equipment e where e.kind=v.kind and e.name=v.name);
insert into public.choices(kind,name,category) values ('process','Washed',''),('process','Natural',''),('process','Honey',''),('process','Anaerobic',''),('pattern','Circular',''),('pattern','Center Pour',''),('pattern','Zigzag',''),('pattern','Slow Pour',''),('pattern','Fast Pour','') on conflict(kind,name) do nothing;
